2	//  CameraScannerView.swift
3	//  SwiftMandarin
4	//
5	//  Camera scanner component using VisionKit DataScannerViewController
6	//  For real-time text recognition from camera
7	//
8	
9	import SwiftUI
10	
11	#if os(iOS)
12	import VisionKit
13	
14	/// SwiftUI wrapper for DataScannerViewController
15	struct CameraScannerView: UIViewControllerRepresentable {
16	    @Binding var recognizedText: String
17	    @Binding var isScanning: Bool
18	    let onTextRecognized: (String) -> Void
19	    let onDismiss: () -> Void
20	    
21	    // Check if device supports data scanning
22	    static var isSupported: Bool {
23	        DataScannerViewController.isSupported
24	    }
25	    
26	    static var isAvailable: Bool {
27	        DataScannerViewController.isAvailable
28	    }
29	    
30	    func makeUIViewController(context: Context) -> UIViewController {
31	        // Double-check availability before creating scanner
32	        guard DataScannerViewController.isSupported && DataScannerViewController.isAvailable else {
33	            // Return a placeholder controller if scanner isn't available
34	            let placeholder = UIViewController()
35	            placeholder.view.backgroundColor = .systemBackground
36	            return placeholder
37	        }
38	        
39	        // Pass the user's scan-language preference so live camera OCR can read
40	        // Chinese (the no-argument `.text()` was locked to system/locale defaults).
41	        let languages = AppPreferences.shared.photoScanLanguage.recognitionLanguages
42	        let scanner = DataScannerViewController(
43	            recognizedDataTypes: [.text(languages: languages)],
44	            qualityLevel: .accurate,
45	            recognizesMultipleItems: true,
46	            isHighFrameRateTrackingEnabled: true,
47	            isPinchToZoomEnabled: true,
48	            isGuidanceEnabled: true,
49	            isHighlightingEnabled: true
50	        )
51	        scanner.delegate = context.coordinator
52	        return scanner
53	    }
54	    
55	    func updateUIViewController(_ uiViewController: UIViewController, context: Context) {
56	        // Only control scanning if we have a DataScannerViewController
57	        guard let scanner = uiViewController as? DataScannerViewController else { return }
58	        
59	        if isScanning {
60	            if !scanner.isScanning {
61	                try? scanner.startScanning()
62	            }
63	        } else {
64	            if scanner.isScanning {
65	                scanner.stopScanning()
66	            }
67	        }
68	    }
69	    
70	    func makeCoordinator() -> Coordinator {
71	        Coordinator(self)
72	    }
73	    
74	    class Coordinator: NSObject, DataScannerViewControllerDelegate {
75	        let parent: CameraScannerView
76	        private var lastRecognizedText: String = ""
77	        
78	        init(_ parent: CameraScannerView) {
79	            self.parent = parent
80	        }
81	        
82	        func dataScanner(_ dataScanner: DataScannerViewController, didTapOn item: RecognizedItem) {
83	            switch item {
84	            case .text(let text):
85	                let cleanedText = cleanTextForSentences(text.transcript)
86	                parent.recognizedText = cleanedText
87	                parent.onTextRecognized(cleanedText)
88	            default:
89	                break
90	            }
91	        }
92	        
93	        func dataScanner(_ dataScanner: DataScannerViewController, didAdd addedItems: [RecognizedItem], allItems: [RecognizedItem]) {
94	            // Combine all recognized text and clean it
95	            let rawText = allItems.compactMap { item -> String? in
96	                if case .text(let text) = item {
97	                    return text.transcript
98	                }
99	                return nil
100	            }.joined(separator: " ")
101	            
102	            let cleanedText = cleanTextForSentences(rawText)
103	            
104	            // Only update if text changed significantly
105	            if cleanedText != lastRecognizedText {
106	                lastRecognizedText = cleanedText
107	                parent.recognizedText = cleanedText
108	            }
109	        }
110	        
111	        func dataScanner(_ dataScanner: DataScannerViewController, didRemove removedItems: [RecognizedItem], allItems: [RecognizedItem]) {
112	            // Update text when items are removed
113	            let rawText = allItems.compactMap { item -> String? in
114	                if case .text(let text) = item {
115	                    return text.transcript
116	                }
117	                return nil
118	            }.joined(separator: " ")
119	            
120	            let cleanedText = cleanTextForSentences(rawText)
121	            lastRecognizedText = cleanedText
122	            parent.recognizedText = cleanedText
123	        }
124	        
125	        /// Clean OCR text in a language-aware way: Chinese text has its
126	        /// inter-character whitespace removed, English text gets sentence cleanup.
127	        private func cleanTextForSentences(_ text: String) -> String {
128	            let language = ChineseTextAnalyzer.shared.detectLanguageRobust(text)
129	            if language.isChinese {
130	                return TextRecognitionResult.cleanChineseText([text])
131	            } else {
132	                return TextRecognitionResult.cleanTextForSentences(text)
133	            }
134	        }
135	        
136	        func dataScanner(_ dataScanner: DataScannerViewController, becameUnavailableWithError error: DataScannerViewController.ScanningUnavailable) {
137	            parent.isScanning = false
138	        }
139	    }
140	}
141	
142	/// Full-screen camera scanner sheet
143	struct CameraScannerSheet: View {
144	    @Environment(\.dismiss) private var dismiss
145	    @Binding var capturedText: String
146	    
147	    @State private var recognizedText: String = ""
148	    @State private var isScanning: Bool = true
149	    @State private var showConfirmation: Bool = false
150	    @State private var scannerError: String?
151	    
152	    private var isScannerAvailable: Bool {
153	        CameraScannerView.isSupported && CameraScannerView.isAvailable
154	    }
155	    
156	    var body: some View {
157	        NavigationStack {
158	            ZStack {
159	                if isScannerAvailable {
160	                    CameraScannerView(
161	                        recognizedText: $recognizedText,
162	                        isScanning: $isScanning,
163	                        onTextRecognized: { text in
164	                            // Optional: Auto-capture on tap
165	                        },
166	                        onDismiss: {
167	                            dismiss()
168	                        }
169	                    )
170	                    .ignoresSafeArea()
171	                    
172	                    // Overlay controls
173	                    VStack {
174	                        Spacer()
175	                        
176	                        // Recognized text preview
177	                        if !recognizedText.isEmpty {
178	                            VStack(spacing: 12) {
179	                                Text("识别到的文字")
180	                                    .font(.caption)
181	                                    .foregroundStyle(.secondary)
182	                                
183	                                ScrollView {
184	                                    Text(recognizedText)
185	                                        .font(.body)
186	                                        .multilineTextAlignment(.leading)
187	                                        .frame(maxWidth: .infinity, alignment: .leading)
188	                                }
189	                                .frame(maxHeight: 120)
190	                                .padding()
191	                                .background(.ultraThinMaterial)
192	                                .clipShape(RoundedRectangle(cornerRadius: 12))
193	                            }
194	                            .padding()
195	                        }
196	                        
197	                        // Capture button
198	                        HStack(spacing: 20) {
199	                            Button {
200	                                dismiss()
201	                            } label: {
202	                                Text("取消")
203	                                    .font(.headline)
204	                                    .foregroundStyle(.white)
205	                                    .frame(width: 80, height: 44)
206	                                    .background(.ultraThinMaterial)
207	                                    .clipShape(Capsule())
208	                            }
209	                            
210	                            Button {
211	                                capturedText = recognizedText
212	                                dismiss()
213	                            } label: {
214	                                Image(systemName: "checkmark.circle.fill")
215	                                    .font(.system(size: 64))
216	                                    .foregroundStyle(.white)
217	                                    .shadow(radius: 4)
218	                            }
219	                            .disabled(recognizedText.isEmpty)
220	                            .opacity(recognizedText.isEmpty ? 0.5 : 1)
221	                            
222	                            Button {
223	                                isScanning.toggle()
224	                            } label: {
225	                                Image(systemName: isScanning ? "pause.fill" : "play.fill")
226	                                    .font(.headline)
227	                                    .foregroundStyle(.white)
228	                                    .frame(width: 80, height: 44)
229	                                    .background(.ultraThinMaterial)
230	                                    .clipShape(Capsule())
231	                            }
232	                        }
233	                        .padding(.bottom, 40)
234	                    }
235	                } else {
236	                    // Scanner not available
237	                    ContentUnavailableView {
238	                        Label("相机不可用", systemImage: "camera.fill")
239	                    } description: {
240	                        if !CameraScannerView.isSupported {
241	                            Text("您的设备不支持文字扫描功能")
242	                        } else {
243	                            Text("请在设置中允许相机访问权限")
244	                        }
245	                    }
246	                }
247	            }
248	            .navigationTitle("扫描文字")
249	            .navigationBarTitleDisplayMode(.inline)
