411	        guard case let .success(urls) = result, !urls.isEmpty else { return }
412	        await MainActor.run { isLoadingWorkbook = true }
413	        let datas = await Self.loadDownscaledFiles(urls)
414	        await MainActor.run {
415	            workbookImages.append(contentsOf: datas)
416	            isLoadingWorkbook = false
417	        }
418	    }
419	
420	    private func addAnswerFiles(_ result: Result<[URL], Error>) async {
421	        guard case let .success(urls) = result, !urls.isEmpty else { return }
422	        await MainActor.run { isLoadingAnswers = true }
423	        let datas = await Self.loadDownscaledFiles(urls)
424	        await MainActor.run {
425	            answerImages.append(contentsOf: datas)
426	            isLoadingAnswers = false
427	        }
428	    }
429	
430	    /// Load each picked Photos item to Data and downscale it for the request.
431	    private static func loadDownscaled(_ items: [PhotosPickerItem]) async -> [Data] {
432	        var datas: [Data] = []
433	        for item in items {
434	            if let data = try? await item.loadTransferable(type: Data.self) {
435	                datas.append(downscaledJPEG(data))
436	            }
437	        }
438	        return datas
439	    }
440	
441	    /// Load each user-selected file URL to Data (security-scoped) and downscale.
442	    private static func loadDownscaledFiles(_ urls: [URL]) async -> [Data] {
443	        var datas: [Data] = []
444	        for url in urls {
445	            let scoped = url.startAccessingSecurityScopedResource()
446	            defer { if scoped { url.stopAccessingSecurityScopedResource() } }
447	            if let data = try? Data(contentsOf: url) {
448	                datas.append(downscaledJPEG(data))
449	            }
450	        }
451	        return datas
452	    }
453	
454	    /// Handle images dragged & dropped onto a bucket (Photos, Finder, Safari, …).
455	    private func handleDrop(_ providers: [NSItemProvider], into target: FileImportTarget) -> Bool {
456	        let imageProviders = providers.filter { $0.hasItemConformingToTypeIdentifier(UTType.image.identifier) }
457	        guard !imageProviders.isEmpty else { return false }
458	
459	        switch target {
460	        case .workbook: isLoadingWorkbook = true
461	        case .answers: isLoadingAnswers = true
462	        }
463	
464	        Task {
465	            var datas: [Data] = []
466	            for provider in imageProviders {
467	                if let data = await Self.loadImageData(from: provider) {
468	                    datas.append(downscaledJPEG(data))
469	                }
470	            }
471	            await MainActor.run {
472	                switch target {
473	                case .workbook:
474	                    workbookImages.append(contentsOf: datas)
475	                    isLoadingWorkbook = false
476	                case .answers:
477	                    answerImages.append(contentsOf: datas)
478	                    isLoadingAnswers = false
479	                }
480	            }
481	        }
482	        return true
483	    }
484	
485	    private static func loadImageData(from provider: NSItemProvider) async -> Data? {
486	        await withCheckedContinuation { continuation in
487	            provider.loadDataRepresentation(forTypeIdentifier: UTType.image.identifier) { data, _ in
488	                continuation.resume(returning: data)
489	            }
490	        }
491	    }
492	
493	    private func grade() async {
494	        await MainActor.run {
495	            isGrading = true
496	            errorMessage = nil
497	            result = nil
498	            savedQuestionIDs = []
499	        }
500	        do {
501	            let graded = try await AIWordExplanationService.shared.gradeWorkbook(
502	                workbookImages: workbookImages,
503	                answerImages: answerImages,
504	                customInstructions: customInstructions.isEmpty ? nil : customInstructions
505	            )
506	            await MainActor.run {
507	                result = graded
508	                isGrading = false
509	            }
510	        } catch {
511	            await MainActor.run {
512	                errorMessage = error.localizedDescription
513	                isGrading = false
514	            }
515	        }
516	    }
517	
518	    private func saveVocab(for question: GradedQuestion) {
519	        Task {
520	            if await saveVocabItem(vocabItem(for: question), question: question) {
521	                await MainActor.run { _ = savedQuestionIDs.insert(question.id) }
522	            }
523	        }
524	    }
525	
526	    private func saveAllWrongVocab() {
527	        guard let result else { return }
528	        let questions = result.wrongQuestions
529	        Task {
530	            for question in questions {
531	                if await saveVocabItem(vocabItem(for: question), question: question) {
532	                    await MainActor.run { _ = savedQuestionIDs.insert(question.id) }
533	                }
534	            }
535	        }
536	    }
537	
538	    /// The word to save for a wrong answer: the model's vocab item if usable,
539	    /// otherwise built from the correct answer so nothing is ever lost.
540	    private func vocabItem(for question: GradedQuestion) -> ExtractedVocabItem {
541	        if let v = question.vocab {
542	            let t = v.term.trimmingCharacters(in: .whitespacesAndNewlines)
543	            let m = v.meaning.trimmingCharacters(in: .whitespacesAndNewlines)
544	            if !t.isEmpty || !m.isEmpty { return v }
545	        }
546	        return ExtractedVocabItem(term: question.correctAnswer, reading: "", meaning: "")
547	    }
548	
549	    /// Save a wrong-answer word to the vocabulary store. The store keys on its
550	    /// headword field, which holds the term in the LEARNING language (the
551	    /// opposite of the interface language): the English word for a 中文-UI
552	    /// student studying English, the Chinese word for an English-UI student
553	    /// studying Mandarin. The other side becomes the definition; a missing
554	    /// headword side is translated, and as a last resort the word is kept
555	    /// as-is rather than silently dropped. When a `question` is given, the
556	    /// correct answer and the student's wrong answer are appended to the
557	    /// definition so the saved card shows what to learn and what was missed.
558	    /// Returns true when a save was attempted.
559	    @discardableResult
560	    private func saveVocabItem(_ item: ExtractedVocabItem, question: GradedQuestion? = nil) async -> Bool {
561	        let term = item.term.trimmingCharacters(in: .whitespacesAndNewlines)
562	        let meaning = item.meaning.trimmingCharacters(in: .whitespacesAndNewlines)
563	        guard !term.isEmpty || !meaning.isEmpty else { return false }
564	
565	        let termIsChinese = term.contains { $0.isChineseCharacter }
566	        let meaningIsChinese = meaning.contains { $0.isChineseCharacter }
567	        let learningChinese = await MainActor.run { LocalizationManager.shared.learningIsChinese }
568	
569	        var chinese: String
570	        var definition: String
571	        if learningChinese {
572	            // Headword should be the Chinese side.
573	            if termIsChinese {
574	                chinese = term
575	                definition = meaning
576	            } else if meaningIsChinese {
577	                chinese = meaning
578	                definition = term
579	            } else {
580	                // Neither side is Chinese — translate the (English) term.
581	                let english = term.isEmpty ? meaning : term
582	                definition = english
583	                if let zh = try? await WordTranslationService.shared.translateToChinese(english),
584	                   zh.contains(where: { $0.isChineseCharacter }) {
585	                    chinese = zh
586	                } else {
587	                    chinese = english  // last resort: keep the word rather than drop it
588	                }
589	            }
590	        } else {
591	            // Studying English: headword should be the English side.
592	            if !termIsChinese, !term.isEmpty {
593	                chinese = term
594	                definition = meaning
595	            } else if !meaningIsChinese, !meaning.isEmpty {
596	                chinese = meaning
597	                definition = term
598	            } else {
599	                // Both sides are Chinese — translate the term to English.
600	                let zhTerm = term.isEmpty ? meaning : term
601	                definition = zhTerm
602	                if let en = try? await WordTranslationService.shared.translateToEnglish(zhTerm),
603	                   !en.contains(where: { $0.isChineseCharacter }), !en.isEmpty {
604	                    chinese = en
605	                } else {
606	                    chinese = zhTerm  // last resort: keep the word rather than drop it
607	                }
608	            }
609	        }
610	
611	        let key = chinese.trimmingCharacters(in: .whitespacesAndNewlines)
612	        guard !key.isEmpty else { return false }
613	        let pinyin = key.contains(where: { $0.isChineseCharacter })
614	            ? (item.reading.isEmpty ? PinyinConverter.convert(key) : item.reading)
615	            : ""
616	        var def = definition.isEmpty ? key : definition
617	
618	        // Pair the correct answer with the student's wrong answer so reviewing
619	        // this card shows both. Skip the correct answer when it merely repeats
620	        // the key/definition to avoid noise.
621	        let correct = (question?.correctAnswer ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
622	        let wrong = (question?.studentAnswer ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
623	        var notes: [String] = []
624	        if !correct.isEmpty,
625	           key.caseInsensitiveCompare(correct) != .orderedSame,
626	           !def.localizedCaseInsensitiveContains(correct) {
627	            notes.append("✓ " + correct)
628	        }
629	        if !wrong.isEmpty, wrong.caseInsensitiveCompare(correct) != .orderedSame {
630	            notes.append("✗ " + wrong)
631	        }
632	        if !notes.isEmpty {
633	            def += "  (" + notes.joined(separator: "  ") + ")"
634	        }
635	
636	        let finalDef = def
637	        await MainActor.run {
638	            if !savedTermsStore.contains(chinese: key) {
639	                savedTermsStore.add(SavedTerm(chinese: key, pinyin: pinyin, definition: finalDef, partOfSpeech: "phrase"))
640	            }
641	        }
642	        return true
643	    }
644	}
645	
646	// MARK: - Graded Question Card
647	
