649	    let question: GradedQuestion
650	    let isSaved: Bool
651	    let onSaveVocab: () -> Void
652	
653	    var body: some View {
654	        VStack(alignment: .leading, spacing: 10) {
655	            HStack(alignment: .top) {
656	                Image(systemName: question.isCorrect ? "checkmark.circle.fill" : "xmark.circle.fill")
657	                    .foregroundStyle(question.isCorrect ? .green : .red)
