718	                    Button {
719	                        onSaveVocab()
720	                    } label: {
721	                        Label(isSaved ? "已保存" : "保存", systemImage: isSaved ? "bookmark.fill" : "bookmark")
722	                    }
723	                    .buttonStyle(.bordered)
724	                    .controlSize(.small)
725	                    .disabled(isSaved)
726	                }
727	            }
728	        }
729	        .padding()
730	        .background(
731	            RoundedRectangle(cornerRadius: 14)
732	                .fill(.background)
733	                .shadow(color: .black.opacity(0.05), radius: 6, y: 3)
734	        )
735	        .overlay(
736	            RoundedRectangle(cornerRadius: 14)
737	                .stroke((question.isCorrect ? Color.green : Color.red).opacity(0.25), lineWidth: 1)
738	        )
739	    }
740	
741	    private func answerRow(label: LocalizedStringKey, value: String, color: Color) -> some View {
742	        HStack(alignment: .firstTextBaseline, spacing: 8) {
743	            Text(label)
744	                .font(.caption)
745	                .foregroundStyle(.secondary)
