753	
754	    /// The complete sentence (in the learning language) with an inline
755	    /// read-aloud button using the voice matching the sentence's language.
756	    private func fullSentenceRow(_ sentence: String) -> some View {
757	        HStack(alignment: .firstTextBaseline, spacing: 8) {
