778	// MARK: - Cross-platform image helpers
779	
780	private func imageFromData(_ data: Data) -> Image? {
781	#if canImport(UIKit)
782	    return UIImage(data: data).map { Image(uiImage: $0) }
783	#elseif canImport(AppKit)
784	    return NSImage(data: data).map { Image(nsImage: $0) }
785	#else
786	    return nil
787	#endif
788	}
789	
790	/// Downscale and JPEG-compress image data via ImageIO so multi-image requests
791	/// stay within reasonable payload/token limits. Applies EXIF orientation.
792	private func downscaledJPEG(_ data: Data, maxDimension: Int = 1536, quality: CGFloat = 0.7) -> Data {
793	    guard let source = CGImageSourceCreateWithData(data as CFData, nil) else { return data }
794	    let options: [CFString: Any] = [
795	        kCGImageSourceCreateThumbnailFromImageAlways: true,
796	        kCGImageSourceCreateThumbnailWithTransform: true,
797	        kCGImageSourceThumbnailMaxPixelSize: maxDimension,
798	    ]
799	    guard let cgImage = CGImageSourceCreateThumbnailAtIndex(source, 0, options as CFDictionary) else { return data }
800	    let output = NSMutableData()
801	    guard let destination = CGImageDestinationCreateWithData(output, UTType.jpeg.identifier as CFString, 1, nil) else {
802	        return data
803	    }
804	    CGImageDestinationAddImage(destination, cgImage, [kCGImageDestinationLossyCompressionQuality: quality] as CFDictionary)
805	    guard CGImageDestinationFinalize(destination) else { return data }
806	    return output as Data
807	}
