10	/// Represents learning activity for a specific day
11	struct DailyActivity: Codable, Identifiable {
12	    var id: String { dateKey }
13	    
14	    /// Date key in format "yyyy-MM-dd"
15	    let dateKey: String
16	    
17	    /// Number of new vocabulary terms saved on this day
18	    var wordsLearned: Int
19	    
20	    /// Number of flashcard reviews completed
21	    var reviewsCompleted: Int
22	    
23	    /// Number of translations made
24	    var translationsMade: Int
25	    
26	    /// Words learned broken down by part of speech
27	    var wordsByPartOfSpeech: [String: Int]
28	    
29	    /// Computed total activity score for heatmap intensity
30	    var activityScore: Int {
31	        wordsLearned * 3 + reviewsCompleted + translationsMade
32	    }
33	    
34	    /// The actual date represented by this activity
35	    var date: Date {
36	        DailyActivity.keyFormatter.date(from: dateKey) ?? Date()
37	    }
38	
39	    /// Formatter for the "yyyy-MM-dd" activity keys. Pinned to the POSIX
40	    /// locale and the Gregorian calendar so keys never pick up localized
41	    /// digits or a non-Gregorian system calendar (which would corrupt the
42	    /// heatmap/streak data). The day boundary intentionally follows the
43	    /// device's local time zone — a "day" of studying is a local day.
44	    static let keyFormatter: DateFormatter = {
45	        let formatter = DateFormatter()
46	        formatter.dateFormat = "yyyy-MM-dd"
47	        formatter.locale = Locale(identifier: "en_US_POSIX")
48	        formatter.calendar = Calendar(identifier: .gregorian)
49	        return formatter
50	    }()
51	
52	    init(dateKey: String, wordsLearned: Int = 0, reviewsCompleted: Int = 0, translationsMade: Int = 0, wordsByPartOfSpeech: [String: Int] = [:]) {
53	        self.dateKey = dateKey
54	        self.wordsLearned = wordsLearned
55	        self.reviewsCompleted = reviewsCompleted
56	        self.translationsMade = translationsMade
57	        self.wordsByPartOfSpeech = wordsByPartOfSpeech
58	    }
59	
60	    init(date: Date, wordsLearned: Int = 0, reviewsCompleted: Int = 0, translationsMade: Int = 0, wordsByPartOfSpeech: [String: Int] = [:]) {
61	        self.dateKey = DailyActivity.keyFormatter.string(from: date)
62	        self.wordsLearned = wordsLearned
63	        self.reviewsCompleted = reviewsCompleted
64	        self.translationsMade = translationsMade
65	        self.wordsByPartOfSpeech = wordsByPartOfSpeech
66	    }
67	}
