69	/// Standard parts of speech categories
70	enum PartOfSpeechCategory: String, CaseIterable, Codable {
71	    case noun = "Noun"
72	    case verb = "Verb"
73	    case adjective = "Adjective"
74	    case adverb = "Adverb"
75	    case pronoun = "Pronoun"
76	    case preposition = "Preposition"
77	    case conjunction = "Conjunction"
78	    case interjection = "Interjection"
79	    case classifier = "Classifier"
80	    case particle = "Particle"
81	    case other = "Other"
82	    
83	    /// Map raw part of speech strings to categories
84	    static func categorize(_ rawPOS: String) -> PartOfSpeechCategory {
85	        let lower = rawPOS.lowercased().trimmingCharacters(in: .whitespacesAndNewlines)
86	        
87	        if lower.isEmpty { return .other }
88	
89	        // Chinese POS labels — AI explanations are written in Mandarin when
90	        // the interface language is 中文, so saved terms carry these values.
91	        // (形容词/副词 are checked before 名词/动词 so compounds match first;
92	        // 助动词 intentionally falls through to the 动词 check.)
93	        if lower.contains("形容词") || lower.contains("形容詞") { return .adjective }
94	        if lower.contains("副词") || lower.contains("副詞") { return .adverb }
95	        if lower.contains("代词") || lower.contains("代詞") { return .pronoun }
96	        if lower.contains("介词") || lower.contains("介詞") { return .preposition }
97	        if lower.contains("连词") || lower.contains("連詞") { return .conjunction }
98	        if lower.contains("叹词") || lower.contains("嘆詞") || lower.contains("感叹词") { return .interjection }
99	        if lower.contains("量词") || lower.contains("量詞") { return .classifier }
100	        if lower.contains("助词") || lower.contains("助詞") { return .particle }
101	        if lower.contains("名词") || lower.contains("名詞") { return .noun }
102	        if lower.contains("动词") || lower.contains("動詞") { return .verb }
103	
104	        // Match common patterns
105	        if lower.contains("noun") { return .noun }
106	        if lower.contains("verb") { return .verb }
107	        if lower.contains("adj") { return .adjective }
108	        if lower.contains("adv") { return .adverb }
109	        if lower.contains("pron") { return .pronoun }
110	        if lower.contains("prep") { return .preposition }
111	        if lower.contains("conj") { return .conjunction }
112	        if lower.contains("interj") { return .interjection }
113	        if lower.contains("class") || lower.contains("measure") { return .classifier }
114	        if lower.contains("part") { return .particle }
115	        
116	        return .other
117	    }
118	    
119	    var color: String {
120	        switch self {
121	        case .noun: return "blue"
122	        case .verb: return "green"
123	        case .adjective: return "orange"
124	        case .adverb: return "purple"
125	        case .pronoun: return "pink"
126	        case .preposition: return "teal"
127	        case .conjunction: return "indigo"
128	        case .interjection: return "red"
129	        case .classifier: return "cyan"
130	        case .particle: return "mint"
131	        case .other: return "gray"
132	        }
133	    }
134	}
