136	/// Observable store that tracks and persists daily learning activity
137	@Observable @MainActor
138	final class LearningActivityStore {
139	    static let shared = LearningActivityStore()
140	    
141	    private let userDefaultsKey = "learningActivities"
142	    
143	    /// Dictionary of date keys to daily activity records
144	    private(set) var activities: [String: DailyActivity] = [:]
145	    
146	    /// Current streak (consecutive days with activity)
147	    var currentStreak: Int {
148	        calculateStreak()
149	    }
150	    
151	    /// Longest streak ever achieved
