16	
17	/// Who the app is centered on. Drives default translation direction,
18	/// default OCR scan language, and which language is emphasized in narration.
19	enum LearnerMode: String, CaseIterable, Identifiable, Codable {
20	    /// English speaker learning Mandarin (the original app audience).
21	    case englishToMandarin
22	    /// Mandarin speaker learning English.
23	    case mandarinToEnglish
24	    /// Learning both languages at once.
25	    case bilingual
26	
27	    var id: String { rawValue }
28	
29	    /// Short label shown in the user's own language emphasis.
30	    var displayName: String {
31	        switch self {
32	        case .englishToMandarin: return "English speaker learning 中文"
33	        case .mandarinToEnglish: return "中文母语者学英语"
34	        case .bilingual: return "Bilingual · 双语学习"
35	        }
36	    }
37	
38	    var shortLabel: String {
39	        switch self {
40	        case .englishToMandarin: return "EN → 中"
41	        case .mandarinToEnglish: return "中 → EN"
42	        case .bilingual: return "EN ⇄ 中"
43	        }
44	    }
45	
46	    var iconName: String {
47	        switch self {
48	        case .englishToMandarin: return "character.book.closed"
49	        case .mandarinToEnglish: return "a.book.closed"
50	        case .bilingual: return "arrow.left.arrow.right.circle"
51	        }
52	    }
53	
54	    var detail: String {
55	        switch self {
56	        case .englishToMandarin:
57	            return "Interface and defaults favor translating into Chinese; narration leads with Mandarin."
58	        case .mandarinToEnglish:
59	            return "界面与默认方向偏向译成英文；朗读以英文为主。"
60	        case .bilingual:
61	            return "Balanced defaults for studying both languages; both narrations are always offered."
62	        }
63	    }
64	
65	    /// The default translation direction this mode implies.
66	    var defaultDirection: TranslationDirection {
67	        switch self {
68	        case .englishToMandarin, .bilingual: return .englishToChinese
69	        case .mandarinToEnglish: return .chineseToEnglish
70	        }
71	    }
72	
73	    /// Whether this mode treats Mandarin as the language the user is learning
74	    /// (so explanations/definitions should be richer in Mandarin) vs. English.
75	    var learningLanguageIsChinese: Bool {
