  phases: [
    { title: 'Find', detail: '13 parallel subsystem/dimension finders' },
    { title: 'Verify', detail: 'adversarially verify high/critical findings' },
    { title: 'Synthesize', detail: 'dedup, prioritize, architecture & workflow recommendations' },
