const SYNTHESIS_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  properties: {
    executiveSummary: { type: 'string' },
    topIssues: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        properties: {
          title: { type: 'string' },
          severity: { type: 'string' },
          why: { type: 'string' },
          fix: { type: 'string' },
        },
        required: ['title', 'severity', 'why', 'fix'],
      },
    },
    architectureRecommendations: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        properties: { title: { type: 'string' }, detail: { type: 'string' }, benefit: { type: 'string' } },
        required: ['title', 'detail', 'benefit'],
      },
    },
    workflowEnhancements: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        properties: { title: { type: 'string' }, detail: { type: 'string' } },
        required: ['title', 'detail'],
      },
    },
    quickWins: { type: 'array', items: { type: 'string' } },
  },
  required: ['executiveSummary', 'topIssues', 'architectureRecommendations', 'workflowEnhancements', 'quickWins'],
}

const AREAS = [
  { key: 'persistence', title: 'Persistence & data models', files: ['SwiftMandarin/Models/PersistentCodableStore.swift', 'SwiftMandarin/Models/SavedTerm.swift', 'SwiftMandarin/Models/LearningActivity.swift', 'SwiftMandarin/Models/LearningCard.swift', 'SwiftMandarin/Models/TranslationHistory.swift', 'SwiftMandarin/Models/ScreenshotTranslationStore.swift'], focus: 'Codable schema-evolution/migration risks (missing keys throwing on decode), UserDefaults size limits for image/large payloads, data-loss on corrupt payloads, store dedup/normalization correctness, @Observable mutation/save amplification.' },
  { key: 'ai', title: 'AI services', files: ['SwiftMandarin/Services/AIWordExplanationService.swift', 'SwiftMandarin/Services/CloudAIService.swift', 'SwiftMandarin/Services/OllamaService.swift', 'SwiftMandarin/Models/AIModelSettings.swift', 'SwiftMandarin/Services/KeychainHelper.swift'], focus: 'error handling, JSON parsing robustness, request timeouts/retries, token/payload limits, provider capability gating, keychain correctness, vision-model selection.' },
  { key: 'photo', title: 'Photo/OCR pipeline', files: ['SwiftMandarin/Views/PhotoTranslateView.swift', 'SwiftMandarin/Services/PhotoTextRecognitionService.swift', 'SwiftMandarin/Views/Components/CameraScannerView.swift', 'SwiftMandarin/Services/ScreenshotStitchingService.swift', 'SwiftMandarin/Services/ChineseTextAnalyzer.swift'], focus: 'OCR correctness, task cancellation/races on rapid re-selection, memory from large images, language detection, error surfacing.' },
  { key: 'workbook', title: 'Workbook grading', files: ['SwiftMandarin/Views/WorkbookGradingView.swift'], focus: 'grading flow correctness, image downscaling, save-to-vocab key correctness, error handling, large multi-image payloads, missing persistence/history.' },
  { key: 'translate', title: 'Translation flows & availability', files: ['SwiftMandarin/Views/TranslateView.swift', 'SwiftMandarin/Services/WordTranslationService.swift', 'SwiftMandarin/Views/Components/CompatModifiers.swift', 'SwiftMandarin/Models/TranslationDirection.swift', 'SwiftMandarin/Models/TranslationState.swift'], focus: 'iOS17/18/26 availability gating correctness, AI fallback paths, debounce/task cancellation, history recording.' },
  { key: 'speech', title: 'Speech', files: ['SwiftMandarin/Services/SpeechRecognitionService.swift', 'SwiftMandarin/Services/SpeechService.swift', 'SwiftMandarin/Views/Components/LiveSpeechTranslationView.swift'], focus: 'audio session leaks, recognizer lifecycle, cancellation correctness, concurrency, error paths.' },
  { key: 'vocab-learn', title: 'Vocabulary & Learn', files: ['SwiftMandarin/Views/VocabularyView.swift', 'SwiftMandarin/Views/LearnView.swift', 'SwiftMandarin/Models/LearningCard.swift', 'SwiftMandarin/Services/VocabularyImportExportService.swift'], focus: 'spaced-repetition correctness, list performance with large vocab, CSV import/export round-trip, sort/dedup, direction-aware display.' },
  { key: 'stats', title: 'Stats & analytics', files: ['SwiftMandarin/Views/StatsView.swift', 'SwiftMandarin/Models/LearningActivity.swift'], focus: 'heatmap correctness, streak edge cases, performance recomputing activities repeatedly, POS categorization, charts.' },
  { key: 'i18n', title: 'Localization & bilingual tailoring', files: ['SwiftMandarin/Models/LocalizationManager.swift', 'SwiftMandarin/Models/TranslationDirection.swift', 'SwiftMandarin/Services/ChineseTextAnalyzer.swift'], focus: 'language-override correctness, native/learning direction logic, locale env propagation to sheets, content-detection edge cases, mixed-script handling.' },
  { key: 'concurrency', title: 'Swift concurrency & MainActor', files: ['SwiftMandarin/Services/AIWordExplanationService.swift', 'SwiftMandarin/Services/SpeechRecognitionService.swift', 'SwiftMandarin/Views/PhotoTranslateView.swift', 'SwiftMandarin/Views/TranslateView.swift'], focus: 'actor isolation, Sendable, data races, unstructured Task leaks, MainActor hops, cancellation propagation.' },
  { key: 'intents', title: 'App Intents & Shortcuts', files: ['SwiftMandarin/Intents/ShortcutHelpers.swift', 'SwiftMandarin/Intents/ShortcutEntities.swift', 'SwiftMandarin/Intents/TranslateScreenshotsIntent.swift', 'SwiftMandarin/Intents/GetLearningStatsIntent.swift', 'SwiftMandarin/Intents/GetRandomPhraseIntent.swift', 'SwiftMandarin/Intents/SwiftMandarinShortcutsProvider.swift'], focus: 'intent correctness, entity queries, MainActor/nonisolated snapshots, error handling, parameter typing across iOS versions.' },
  { key: 'architecture', title: 'Architecture, navigation & UX', files: ['SwiftMandarin/ContentView.swift', 'SwiftMandarin/Views/MoreView.swift', 'SwiftMandarin/SwiftMandarinApp.swift', 'SwiftMandarin/Models/AppRouteStore.swift', 'SwiftMandarin/Views/MacOSSettingsView.swift'], focus: '8-tab navigation intuitiveness, More-tab clutter/redundancy (History tab duplicates More->History), settings organization, discoverability of tucked-away features, cross-platform structure. Propose a more intuitive, natural, streamlined IA.' },
  { key: 'components', title: 'Reusable components & rendering', files: ['SwiftMandarin/Views/Components/RubyTextView.swift', 'SwiftMandarin/Views/Components/EnglishRubyTextView.swift', 'SwiftMandarin/Views/Components/AIWordExplanationView.swift', 'SwiftMandarin/Views/Components/TranslatedScreenshotOverlayView.swift', 'SwiftMandarin/Views/Components/AIProviderConfigView.swift'], focus: 'rendering performance, layout correctness, reuse opportunities, accessibility, state handling.' },
]

phase('Find')
log(`Auditing ${AREAS.length} subsystems of SwiftMandarin in parallel`)
const finderResults = await parallel(AREAS.map(a => () =>
  agent(
    `You are a senior iOS/Swift auditor reviewing the SwiftMandarin iOS/macOS SwiftUI app. Repo root: ${ROOT}.\n` +
    `This is a STRICTLY READ-ONLY audit — do NOT modify, create, or delete any files; only Read/Grep.\n\n` +
    `Audit the **${a.title}** subsystem. Read these files fully first:\n${a.files.map(f => '- ' + ROOT + '/' + f).join('\n')}\n\n` +
    `Focus areas: ${a.focus}\n\n` +
    `Report every concrete defect you can substantiate — bugs, bottlenecks, errors, race conditions, data-loss risks, memory issues, accessibility gaps, and notable code smells — each with precise file:line evidence and a concrete fix. Separately, list improvement/optimization suggestions that would make this subsystem more powerful, robust, intuitive, and streamlined. Be precise and skeptical; do not invent issues. Severity: critical=crash/data-loss/security, high=wrong behavior users hit, medium=edge case/perf, low=polish.`,
    { label: `find:${a.key}`, phase: 'Find', schema: FINDING_SCHEMA }
  )
))

const finders = finderResults.map((r, i) => ({ area: AREAS[i].key, result: r })).filter(x => x.result)
const allFindings = finders.flatMap(f => (f.result.findings || []).map(x => ({ ...x, area: f.area })))
const allSuggestions = finders.flatMap(f => (f.result.suggestions || []).map(x => ({ ...x, area: f.area })))
log(`Collected ${allFindings.length} findings, ${allSuggestions.length} suggestions`)

phase('Verify')
const toVerify = allFindings.filter(f => f.severity === 'critical' || f.severity === 'high')
log(`Adversarially verifying ${toVerify.length} high/critical findings`)
const verified = await parallel(toVerify.map(f => () =>
  agent(
    `Adversarially verify a claimed issue in the SwiftMandarin codebase (root ${ROOT}). READ-ONLY: only Read/Grep the cited files; reach an independent verdict.\n\n` +
    `Claim: "${f.title}" (severity ${f.severity}, category ${f.category})\n` +
    `Files: ${(f.files || []).join(', ')}\n` +
    `Evidence given: ${f.evidence}\n` +
    `Impact claimed: ${f.impact}\n` +
    `Proposed fix: ${f.recommendation}\n\n` +
    `Open the files and check the claim against the actual code. Confirm ONLY if the defect is real and reachable. Default to confirmed=false when the evidence does not hold up. Adjust severity if warranted.`,
    { label: `verify:${f.area}`, phase: 'Verify', schema: VERDICT_SCHEMA }
  ).then(v => ({ ...f, verdict: v }))
))
const verifiedConfirmed = verified.filter(Boolean).filter(v => v.verdict && v.verdict.confirmed)
const verifiedRefuted = verified.filter(Boolean).filter(v => v.verdict && !v.verdict.confirmed)
log(`Verified: ${verifiedConfirmed.length} confirmed, ${verifiedRefuted.length} refuted`)

phase('Synthesize')
const lowerFindings = allFindings.filter(f => f.severity !== 'critical' && f.severity !== 'high')
const synthesis = await agent(
  `You are the lead architect synthesizing a full audit of the SwiftMandarin iOS/macOS Mandarin-learning app (a SwiftUI app: 8 tabs — Translate, Photo, History, Vocabulary, Learn, Phrases, Stats, More; @Observable @MainActor singleton stores over UserDefaults JSON; 10-provider AI abstraction; bilingual English<->Chinese; workbook photo grading).\n\n` +
  `CONFIRMED high/critical findings (JSON):\n${JSON.stringify(verifiedConfirmed.map(v => ({ title: v.title, severity: v.verdict.adjustedSeverity, area: v.area, evidence: v.evidence, fix: v.recommendation })))}\n\n` +
  `Lower-severity findings (JSON):\n${JSON.stringify(lowerFindings.map(f => ({ title: f.title, severity: f.severity, area: f.area, recommendation: f.recommendation })))}\n\n` +
  `Improvement suggestions (JSON):\n${JSON.stringify(allSuggestions)}\n\n` +
  `Produce: (1) a crisp executive summary of codebase health; (2) the top prioritized issues to fix; (3) architecture recommendations to make the app more powerful, robust, intuitive, natural, and streamlined (esp. data layer, navigation/IA, the tucked-away workbook features, the cluttered More tab); (4) workflow enhancements that make the learning workflow more capable and comprehensive; (5) quick wins. Be specific and actionable.`,
  { label: 'synthesize', phase: 'Synthesize', schema: SYNTHESIS_SCHEMA }
)

return {
  counts: { findings: allFindings.length, suggestions: allSuggestions.length, verifiedConfirmed: verifiedConfirmed.length, verifiedRefuted: verifiedRefuted.length },
  allFindings,
  allSuggestions,
  verifiedConfirmed: verifiedConfirmed.map(v => ({ ...v, verdict: v.verdict })),
  verifiedRefuted: verifiedRefuted.map(v => ({ title: v.title, area: v.area, reasoning: v.verdict.reasoning })),
  synthesis,
}

